// Regenerates src/components/hero/graph-data.ts from buildGraph(). Run: npm run gen:graph
import { writeFileSync } from "node:fs";
import { buildGraph } from "../src/components/hero/graph";
const g = buildGraph();
writeFileSync(
  "src/components/hero/graph-data.ts",
  `/**
 * GENERATED by buildGraph() in graph.ts. Do not edit by hand.
 * Precomputed so the browser never runs the force layout (it cost ~90 ms of main thread at 4×
 * CPU throttling). tests/hero.spec.ts fails if this drifts from buildGraph().
 */
import type { Graph } from "./graph";

export const GRAPH_DATA: Graph = ${JSON.stringify(g)};
`,
);
